import{S as o,o as s,c as i,a9 as d,B as n}from"./chunks/framework.IJ8axLs_.js";const r="/agentsrc/images/claudecode/01-macro-architecture.svg",l="/agentsrc/images/claudecode/01-layers.svg",u=JSON.parse('{"title":"Claude Code 整体架构：51 万行代码怎么组织成一个终端 Agent","description":"","frontmatter":{"title":"Claude Code 整体架构：51 万行代码怎么组织成一个终端 Agent"},"headers":[],"relativePath":"claudecode/01-overview.md","filePath":"claudecode/01-overview.md","lastUpdated":1790217011000}'),c={name:"claudecode/01-overview.md"},g=Object.assign(c,{setup(h){const t=[{question:"Claude Code 本地代码与模型能力的关系，准确的说法是？",options:["本地含轻量推理逻辑，小任务端上直接出结果","本地只做编排，模型能力全部来自云端 API","本地跑一个量化小模型，云端只做复杂任务","本地与云端各推理一半，结果在本地合并"],correct:1,explanation:"Claude Code 是纯客户端编排器：组织上下文、发流式请求、本地执行工具、回填结果再请求。51 万行全部花在编排上，没有自研模型代码。A/C/D 的端侧推理均不存在。"},{question:"`hooks/` 目录 104 个文件在四层架构中的位置，正确的是？",options:["属于表现层，只负责组件渲染与事件绑定","属于业务逻辑层，负责注册命令与工具","物理归基础设施层，运行期横跨表现与业务层","属于服务层，封装 API 与 MCP 外部交互"],correct:2,explanation:"hooks 物理上在基础设施层，运行期绑定在组件树上，既调用业务层的 QueryEngine 又调用服务层能力，是跨层胶水。这也意味着理解功能需要在 hooks 与组件之间来回跳转。"},{question:"启动时把钥匙串预取放在所有 import 之前，目的是什么？",options:["规避模块循环依赖导致的求值死锁","让 IO 等待与 CPU 密集的模块导入并行","确保身份认证先于任何业务代码执行","提前校验配置文件格式避免启动失败"],correct:1,explanation:"模块导入约 135ms 且 CPU 密集，钥匙串读取是 IO 等待、可并行。提前发射可以把 IO 塞进导入间隙，省下约 65ms 的串行等待，等导入完成时数据大概率已就绪。"},{question:"continuation-driven 主循环的「继续或终止」由什么决定？",options:["外部循环变量计数到达上限后退出","定时器到期后强制进入下一轮请求","本轮流式响应里是否出现工具调用","用户每轮手动确认后才继续执行"],correct:2,explanation:"循环体是 while(true)，退出信号是 tool_use 块到达时置位的 needsFollowUp——源码注释明确 stop_reason 字段不可靠，不能作为依据。没有工具调用就终止并把控制权交还 REPL；好处是没有忙等，每轮 await 流式响应。"},{question:"无沙箱前提下，Claude Code 管控工具执行风险的核心机制是？",options:["所有命令都在一次性容器里执行后销毁","七种模式分级的权限系统做放行决策","靠网络隔离切断工具的外部访问路径","靠只读文件系统限制工具的写入范围"],correct:1,explanation:"Codex 用沙箱兜底，Claude Code 把安全责任上移到权限决策点：5 个外部模式加 2 个内部模式，auto 模式由 AI 分类器实时评估风险。权限是贯穿各层的横切关注点，容器与网络隔离在三者中都不存在。"}];return(p,e)=>{const a=o("Quiz");return s(),i("div",null,[e[0]||(e[0]=d("",59)),n(a,{questions:t})])}}});export{u as __pageData,g as default};
